71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Dedicated audit logger. On a successful create an audit line carrying the new owner's id,
75	     * {@code customerCode}, {@code registrationDate} and {@code membershipLevel} is emitted to the
76	     * logger named {@code AUDIT}.
77	     */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    /**
81	     * Syntactic check for an email address: a non-empty local part, an {@code @}, and a domain with
82	     * at least one dot and no whitespace on either side.
83	     */
84	    private static final Pattern EMAIL_PATTERN =
85	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
86	
87	    /**
88	     * Disposable email domains that an owner's email may not use. An email whose domain (the part
89	     * after the {@code @}, compared case-insensitively) is on this list is rejected with a 400
90	     * response naming {@code email}.
91	     */
92	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
93	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
94	
95	    /**
96	     * Common street-type abbreviations expanded during address normalization. Keys are the
97	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
98	     * expanded form.
99	     */
100	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
101	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
102	
103	    /**
104	     * Required national-number length per E.164 country code (the digits that follow the country
105	     * code). {@code '+61'} (Australia) requires 9 national digits; {@code '+1'} (NANP) requires 10.
106	     * A country code that is not listed here is not length-checked, keeping other numbers accepted.
107	     */
108	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH =
109	        Map.of("1", 10, "61", 9);
110	
111	    /**
112	     * Inclusive 4-digit postcode range allowed for each known region, keyed by the region an owner's
113	     * city derives to (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD): NSW 2000-2099, VIC
114	     * 3000-3099, QLD 4000-4099. A city that derives to no known region ({@code "UNKNOWN"}) is not in
115	     * this table and accepts any 4-digit postcode.
116	     */
117	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
118	        "NSW", new int[] {2000, 2099},
119	        "VIC", new int[] {3000, 3099},
120	        "QLD", new int[] {4000, 4099});
121	
122	    /**
123	     * The maximum number of owners a single city may contain. A create request for a city that
124	     * already holds this many owners is rejected with a 409 response.
125	     */
126	    private static final int MAX_OWNERS_PER_CITY = 50;
127	
128	    /**
129	     * The maximum number of owners that may be registered in a single day. A create request made
130	     * once this many owners already carry today's {@code registrationDate} is rejected with a 429
131	     * response.
132	     */
133	    private static final int MAX_OWNERS_PER_DAY = 100;
134	
135	    /**
136	     * The number of owners that must already carry a day's {@code registrationDate} before a create
137	     * for that day is flagged as a bulk signup. Once more than this many owners already exist for the
138	     * day, the new owner is created with {@code bulkSignupWarning} set to {@code true}.
139	     */
140	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
141	
142	    /**
143	     * The tenure, in days, an owner must exceed to reach {@code membershipLevel} 4. Tenure accrues
144	     * from membership, so a newly created owner (zero tenure) never clears this threshold and is
145	     * therefore capped at level 3 on create.
146	     */
147	    private static final int TENURE_LEVEL_THRESHOLD_DAYS = 365;
