319	    /**
320	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
321	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
322	     * does not catch). The names of all offending fields are collected so the caller receives a
323	     * 400 response whose {@code errors} array lists each one.
324	     */
325	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
326	        List<String> missingFields = new ArrayList<>();
327	        if (isBlank(ownerFieldsDto.getFirstName())) {
328	            missingFields.add("firstName");
329	        }
330	        if (isBlank(ownerFieldsDto.getLastName())) {
331	            missingFields.add("lastName");
332	        }
333	        if (isBlank(ownerFieldsDto.getAddress())) {
334	            missingFields.add("address");
335	        }
336	        if (isBlank(ownerFieldsDto.getCity())) {
337	            missingFields.add("city");
338	        }
339	        if (isBlank(ownerFieldsDto.getTelephone())) {
340	            missingFields.add("telephone");
341	        }
342	        if (!missingFields.isEmpty()) {
343	            throw new InvalidOwnerFieldsException(missingFields);
344	        }
345	    }
346	
347	    private static boolean isBlank(String value) {
348	        return value == null || value.trim().isEmpty();
349	    }
350	
351	    /**
352	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
353	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
354	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
355	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
356	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
357	     * means an address that is blank after normalization is rejected like a missing one.
358	     */
359	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
360	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
361	    }
362	
363	    /**
364	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
365	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
366	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
367	     * address is returned unchanged, making it safe to apply to stored values during comparison.
368	     */
369	    private static String canonicalAddress(String address) {
370	        if (address == null) {
371	            return null;
372	        }
373	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
374	        if (collapsed.isEmpty()) {
375	            return "";
376	        }
377	        String[] tokens = collapsed.split(" ");
378	        StringBuilder sb = new StringBuilder(collapsed.length());
379	        for (int i = 0; i < tokens.length; i++) {
380	            if (i > 0) {
381	                sb.append(' ');
382	            }
383	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
384	        }
385	        return sb.toString();
386	    }
387	
388	    /**
389	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
390	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
391	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
392	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
393	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
394	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
395	     * written back onto the request so it is what gets stored and returned. Any value that cannot
396	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
397	     * {@code telephone}.
398	     */
399	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
400	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
401	    }
402	
403	    /**
404	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
405	     * (400) naming {@code telephone} when it cannot form a valid number.
406	     */
407	    private static String toE164(String telephone) {
408	        if (telephone == null) {
409	            throw new InvalidOwnerFieldsException(List.of("telephone"));
410	        }
411	        boolean hasCountryCode = telephone.trim().startsWith("+");
412	        String digits = telephone.replaceAll("\\D", "");
413	        String countryCode;
414	        String national;
415	        if (hasCountryCode) {
416	            countryCode = matchCountryCode(digits);
417	            national = digits;
418	        } else {
419	            countryCode = "61";
420	            if (digits.startsWith("0")) {
421	                digits = digits.substring(1);
422	            }
423	            national = "61" + digits;
424	        }
425	        if (!national.matches("[0-9]{8,15}")) {
426	            throw new InvalidOwnerFieldsException(List.of("telephone"));
427	        }
428	        if (countryCode != null) {
429	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
430	            if (requiredLength != null
431	                && national.length() - countryCode.length() != requiredLength) {
432	                throw new InvalidOwnerFieldsException(List.of("telephone"));
433	            }
434	        }
435	        return "+" + national;
436	    }
437	
438	    /**
439	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
440	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
441	     * the number is not length-checked against a country.
442	     */
443	    private static String matchCountryCode(String digits) {
444	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
445	            .filter(digits::startsWith)
446	            .max(Comparator.comparingInt(String::length))
447	            .orElse(null);
448	    }
449	
450	    /**
451	     * Rejects creating an owner that duplicates an existing one, either as a household duplicate or
452	     * as an exact identity duplicate. The household is now keyed on the computed {@code householdId}
453	     * (a deterministic function of the normalized last name and postcode, see
454	     * {@link #computeHouseholdId}), so any existing owner already carrying the same {@code householdId}
455	     * belongs to the same household and makes the new owner a household duplicate. Independently, an
456	     * exact match on the derived {@code identityKey} - {@code normalizedTelephone + '|' + (email or
457	     * empty) + '|' + (householdId or empty)} - is also a duplicate; this still catches owners with no
458	     * postcode (and therefore no household) that share a telephone and email. Both checks are a 409.
459	     *
460	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block: a request that opts in
461	     * is allowed through even when it lands in an existing household, so it is created as a declared
462	     * household member rather than rejected. The incoming telephone and email have already been
463	     * normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}; each existing owner's key
464	     * is derived the same way before comparison. A match results in a 409 response naming
465	     * {@code identityKey}.
466	     */
467	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto, String householdId) {
468	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
469	            return;
470	        }
471	        String identityKey = identityKey(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), householdId);
472	        for (Owner existing : this.clinicService.findAllOwners()) {
473	            boolean householdDuplicate = householdId != null && householdId.equals(existing.getHouseholdId());
474	            if (householdDuplicate || identityKey.equals(existingIdentityKey(existing))) {
475	                throw new DuplicateOwnerIdentityException(identityKey);
476	            }
477	        }
478	    }
479	
480	    /**
481	     * Builds an {@code identityKey} from its three parts: {@code telephone + '|' + email + '|' +
482	     * householdId}, with a {@code null} part contributing the empty string. The telephone and email
483	     * are expected to already be in their normalized (E.164, lower-cased) forms.
484	     */
485	    private static String identityKey(String telephone, String email, String householdId) {
486	        return orEmpty(telephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
487	    }
488	
489	    /**
490	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
491	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
492	     * the stored email is lower-cased, and the stored household id is used as-is.
493	     */
494	    private static String existingIdentityKey(Owner existing) {
495	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
496	        String email = existing.getEmail() == null ? "" : existing.getEmail().toLowerCase(Locale.ROOT);
497	        return identityKey(telephone, email, existing.getHouseholdId());
498	    }
499	
500	    private static String orEmpty(String value) {
501	        return value == null ? "" : value;
502	    }
503	
504	    /**
505	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
506	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
507	     */
508	    private static String normalizeExisting(String telephone) {
509	        try {
510	            return toE164(telephone);
511	        } catch (InvalidOwnerFieldsException ex) {
512	            return null;
513	        }
514	    }
515	
516	    /**
517	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
518	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
519	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
520	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
521	     */
522	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
523	        String city = ownerFieldsDto.getCity();
524	        int count = 0;
525	        for (Owner existing : this.clinicService.findAllOwners()) {
526	            if (city.equalsIgnoreCase(existing.getCity())) {
527	                count++;
528	            }
529	        }
530	        if (count >= MAX_OWNERS_PER_CITY) {
531	            throw new OwnerCityAtCapacityException(city);
532	        }
533	    }
534	
535	    /**
536	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
537	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
538	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
539	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
540	     */
541	    private void rejectDailyLimitReached(LocalDate registrationDate) {
542	        int count = 0;
543	        for (Owner existing : this.clinicService.findAllOwners()) {
544	            if (registrationDate.equals(existing.getRegistrationDate())) {
545	                count++;
546	            }
547	        }
548	        if (count >= MAX_OWNERS_PER_DAY) {
549	            throw new DailyOwnerLimitReachedException(registrationDate);
550	        }
551	    }
552	
553	    /**
554	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
555	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
556	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
557	     */
558	    private static String normalizeForComparison(String value) {
559	        if (value == null) {
560	            return "";
561	        }
562	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
563	    }
564	
565	    /**
566	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
567	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
568	     * written back onto the request so that is what gets stored and returned. A present but invalid
569	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
570	     */
571	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
572	        String email = ownerFieldsDto.getEmail();
573	        if (email == null) {
574	            return;
575	        }
576	        String trimmed = email.trim();
577	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
578	            throw new InvalidOwnerFieldsException(List.of("email"));
579	        }
580	        String normalized = trimmed.toLowerCase(Locale.ROOT);
581	        String domain = normalized.substring(normalized.indexOf('@') + 1);
582	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
583	            throw new InvalidOwnerFieldsException(List.of("email"));
584	        }
585	        ownerFieldsDto.setEmail(normalized);
586	    }
587	
588	    /**
589	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
590	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
591	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
592	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
593	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
594	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
595	     * as-is so it is stored and returned.
596	     */
597	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
598	        String postcode = ownerFieldsDto.getPostcode();
599	        if (postcode == null) {
600	            return;
601	        }
602	        if (!postcode.matches("[0-9]{4}")) {
603	            throw new InvalidOwnerFieldsException(List.of("postcode"));
604	        }
605	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
606	        if (range != null) {
607	            int value = Integer.parseInt(postcode);
608	            if (value < range[0] || value > range[1]) {
609	                throw new InvalidOwnerFieldsException(List.of("postcode"));
610	            }
611	        }
612	    }
613	
614	    /**
615	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
616	     * day. When the caller supplies no value it defaults to the server's current date; a value
617	     * provided in the request is kept. A supplied value later than the server's current date is
618	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
619	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
620	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
621	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
622	     * every value derived from the registration date is based on.
623	     */
624	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
625	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
626	        if (effective == null) {
627	            effective = LocalDate.now();
628	        }
629	        else if (effective.isAfter(LocalDate.now())) {
630	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
631	        }
632	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
633	    }
634	
635	    /**
636	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
637	     * Monday; a weekday is returned unchanged.
638	     */
639	    private static LocalDate toBusinessDay(LocalDate date) {
640	        return switch (date.getDayOfWeek()) {
641	            case SATURDAY -> date.plusDays(2);
642	            case SUNDAY -> date.plusDays(1);
643	            default -> date;
644	        };
645	    }
646	
647	    /**
648	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
649	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
650	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
651	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
652	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
653	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
654	     * pure function of region, telephone and last name.
655	     */
656	    private void assignCustomerCode(Owner owner) {
657	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
658	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
659	        owner.setCustomerCode(region + "-" + hash8);
660	    }
661	
662	    /**
663	     * Assigns the owner's {@code membershipNumber} on create, formatted
664	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
665	     * {@code registrationDate} year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Assigned after
666	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
667	     * inputs are present.
668	     */
669	    private void assignMembershipNumber(Owner owner) {
670	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
671	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
672	    }
673	
674	    /**
675	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
676	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
677	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
678	     */
679	    private void assignNamesakeCount(Owner owner) {
680	        String firstName = owner.getFirstName();
681	        String lastName = owner.getLastName();
682	        int count = 0;
683	        for (Owner existing : this.clinicService.findAllOwners()) {
684	            if (firstName.equalsIgnoreCase(existing.getFirstName())
685	                && lastName.equalsIgnoreCase(existing.getLastName())) {
686	                count++;
687	            }
688	        }
689	        owner.setNamesakeCount(count);
690	    }
691	
692	    /**
693	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
694	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
695	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
696	     * {@value #TENURE_LEVEL_THRESHOLD_DAYS} days. The points are then mapped to a level of 1 (0-1
697	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
698	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
699	     * tenure, so the tenure bonus never applies on create.
700	     */
701	    private void assignMembership(Owner owner) {
702	        int points = 0;
703	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
704	            points += 2;
705	        }
706	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
707	            points += 1;
708	        }
709	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
710	            points += 2;
711	        }
712	        if (tenureDays(owner) > TENURE_LEVEL_THRESHOLD_DAYS) {
713	            points += 3;
714	        }
715	        owner.setMembershipPoints(points);
716	        owner.setMembershipLevel(membershipLevelForPoints(points));
717	    }
718	
719	    /**
720	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
721	     * 4-5, and 4 for 6 or more points.
722	     */
723	    private int membershipLevelForPoints(int points) {
724	        if (points <= 1) {
725	            return 1;
726	        }
727	        if (points <= 3) {
728	            return 2;
729	        }
730	        if (points <= 5) {
731	            return 3;
732	        }
733	        return 4;
734	    }
735	
736	    /**
737	     * The tenure, in days, of a newly created owner. Tenure accrues from membership over time, and a
738	     * new owner has not been a member for any elapsed time yet, so this is always {@code 0} on create
739	     * (regardless of any backdated {@code registrationDate}).
740	     */
741	    private long tenureDays(Owner owner) {
742	        return 0L;
743	    }
744	
745	    /**
746	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
747	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
748	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
749	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
750	     * pre-existing owners for that day.
751	     */
752	    private void assignBulkSignupWarning(Owner owner) {
753	        LocalDate registrationDate = owner.getRegistrationDate();
754	        int count = 0;
755	        for (Owner existing : this.clinicService.findAllOwners()) {
756	            if (registrationDate.equals(existing.getRegistrationDate())) {
757	                count++;
758	            }
759	        }
760	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
761	    }
762	
763	    /**
764	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
765	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
766	     * possible duplicate when an existing owner shares its {@code lastName} (compared
767	     * case-insensitively) and its {@code postcode} (a present, exact match) while carrying a different
768	     * {@code telephone}. When such an owner exists, {@code possibleDuplicate} is set to {@code true}
769	     * and {@code possibleDuplicateOf} to that owner's id (the lowest id when several match); otherwise
770	     * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} is left {@code null}.
771	     * Computed before the new owner is persisted, so it considers only the pre-existing owners.
772	     *
773	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
774	     * has deliberately opted into an existing household, so its shared last name and postcode are
775	     * expected rather than a suspected duplicate.
776	     */
777	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
778	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
779	            owner.setPossibleDuplicate(false);
780	            owner.setPossibleDuplicateOf(null);
781	            return;
782	        }
783	        String lastName = owner.getLastName();
784	        String postcode = owner.getPostcode();
785	        String telephone = owner.getTelephone();
786	        Integer matchId = null;
787	        if (postcode != null) {
788	            for (Owner existing : this.clinicService.findAllOwners()) {
789	                if (lastName.equalsIgnoreCase(existing.getLastName())
790	                    && postcode.equals(existing.getPostcode())
791	                    && !postcode.isBlank()
792	                    && !java.util.Objects.equals(telephone, existing.getTelephone())
793	                    && existing.getId() != null
794	                    && (matchId == null || existing.getId() < matchId)) {
795	                    matchId = existing.getId();
796	                }
797	            }
798	        }
799	        owner.setPossibleDuplicate(matchId != null);
800	        owner.setPossibleDuplicateOf(matchId);
801	    }
802	
803	    /**
804	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
805	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
806	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
807	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
808	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
809	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
810	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
811	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
812	     * ({@link #assignHouseholdMembership}).
813	     */
814	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
815	        String postcode = ownerFieldsDto.getPostcode();
816	        if (postcode == null || postcode.isBlank()) {
817	            return null;
818	        }
819	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
820	        return shaHexUpper(lastName + "|" + postcode, 12);
821	    }
822	
823	    /**
824	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
825	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
826	     * every existing owner already carrying the same identifier. Runs after the owner's
827	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
828	     * Left {@code null} when the owner belongs to no household.
829	     */
830	    private void assignHouseholdMembership(Owner owner) {
831	        String householdId = owner.getHouseholdId();
832	        if (householdId == null || householdId.isBlank()) {
833	            owner.setHouseholdMemberCount(null);
834	            return;
835	        }
836	        int count = 1;
837	        for (Owner existing : this.clinicService.findAllOwners()) {
838	            if (householdId.equals(existing.getHouseholdId())) {
839	                count++;
840	            }
841	        }
842	        owner.setHouseholdMemberCount(count);
843	    }
844	
845	    /**
846	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
847	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
848	     * identifier, both stable functions of their inputs.
849	     */
850	    private static String shaHexUpper(String input, int length) {
851	        try {
852	            byte[] digest = MessageDigest.getInstance("SHA-256")
853	                .digest(input.getBytes(StandardCharsets.UTF_8));
854	            StringBuilder hex = new StringBuilder(digest.length * 2);
855	            for (byte b : digest) {
856	                hex.append(String.format("%02x", b));
857	            }
858	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
859	        } catch (NoSuchAlgorithmException ex) {
860	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
861	        }
862	    }
863	}
