1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (region) from the postcode and city.
7	 *
8	 * <p>The postcode is preferred: a 4-digit postcode falling in a known region range (NSW 2000-2099,
9	 * VIC 3000-3099, QLD 4000-4099) fixes the region and disambiguates cities that share a name. Only
10	 * when the postcode is absent or in no known range does derivation fall back to the fixed
11	 * city-to-region table.
12	 *
13	 * <p>Kept as a standalone helper rather than a method on {@link OwnerMapper}: a single-argument
14	 * {@code String}-to-{@code String} method declared on a MapStruct mapper would be picked up as an
15	 * implicit conversion and applied to every String property mapping.
16	 */
17	public final class OwnerLocality {
18	
19	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
20	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
21	        "NSW", new int[] {2000, 2099},
22	        "VIC", new int[] {3000, 3099},
23	        "QLD", new int[] {4000, 4099});
24	
25	    private OwnerLocality() {
26	    }
27	
28	    /**
29	     * Returns the canonical region, preferring the {@code postcode}: a postcode in a known region
30	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) selects that region. When the postcode is
31	     * absent, malformed, or in no known range, falls back to the city-to-region table via
32	     * {@link #derive(String)}.
33	     */
34	    public static String derive(String city, String postcode) {
35	        String fromPostcode = regionForPostcode(postcode);
36	        if (fromPostcode != null) {
37	            return fromPostcode;
38	        }
39	        return derive(city);
40	    }
41	
42	    /**
43	     * Returns the canonical region for {@code city} (Sydney-&gt;NSW, Melbourne-&gt;VIC,
44	     * Brisbane-&gt;QLD), or {@code "UNKNOWN"} when the city is not in the table.
45	     */
46	    public static String derive(String city) {
47	        if (city == null) {
48	            return "UNKNOWN";
49	        }
50	        switch (city) {
51	            case "Sydney":
52	                return "NSW";
53	            case "Melbourne":
54	                return "VIC";
55	            case "Brisbane":
56	                return "QLD";
57	            default:
58	                return "UNKNOWN";
59	        }
60	    }
61	
62	    /**
63	     * Returns the region an owner's identity resolves to by reading it back off the
64	     * {@code customerCode}, which is formatted {@code '<REGION>-<HASH8>'}: the portion before the
65	     * first {@code '-'}. The locality therefore shares the single region-and-hash identity assigned
66	     * at creation instead of being recomputed from the city and postcode. Returns {@code "UNKNOWN"}
67	     * when the customer code is absent, blank, or carries no region segment.
68	     */
69	    public static String fromCustomerCode(String customerCode) {
70	        if (customerCode == null || customerCode.isBlank()) {
71	            return "UNKNOWN";
72	        }
73	        int dash = customerCode.indexOf('-');
74	        String region = dash < 0 ? customerCode : customerCode.substring(0, dash);
75	        return region.isBlank() ? "UNKNOWN" : region;
76	    }
77	
78	    /** Region for a 4-digit {@code postcode} in a known range, or {@code null} otherwise. */
79	    private static String regionForPostcode(String postcode) {
80	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
81	            return null;
82	        }
83	        int value = Integer.parseInt(postcode);
84	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
85	            int[] range = entry.getValue();
86	            if (value >= range[0] && value <= range[1]) {
87	                return entry.getKey();
88	            }
89	        }
90	        return null;
91	    }
92	}
